        if inner is not None:
            calls.append(inner)
    best = None
    for call in calls:
        try:
            for _ in range(4):
                call(gx, gy, gz, sget(), fnp, pm, None, None, None, *args)
            torch.npu.synchronize()
            t0 = time.perf_counter()
            for _ in range(16):
