            torch.npu.synchronize()
            dt = time.perf_counter() - t0
        except Exception:
            continue
        if best is None or dt < best[0]:
            best = (dt, call)
    if best is None:
        return None
    call = best[1]

    def launch(xin, out, buf, w, b):
        call(gx, gy, gz, sget(), fnp, pm, None, None, None, xin, out, buf, w, b)

    return launch'
